import Complex128Array = require( '@stdlib/array/complex128' );
import zvander = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander( 'row-major', -1, 10, 10, x, 1, out, 10 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander( '10', -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 10, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( true, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( false, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( null, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( undefined, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( [], -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( {}, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( ( x: number ): number => x, -1, 10, 10, x, 1, out, 10 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander( 'row-major', '10', 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', true, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', false, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', null, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', undefined, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', [], 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', {}, 10, 10, x, 1, out, 10 ); // $ExpectError
	zvander( 'row-major', ( x: number ): number => x, 10, 10, x, 1, out, 10 ); // $ExpectError
}

