// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander(); // $ExpectError
	zvander( 'row-major' ); // $ExpectError
	zvander( 'row-major', -1 ); // $ExpectError
	zvander( 'row-major', -1, 10 ); // $ExpectError
	zvander( 'row-major', -1, 10, 10 ); // $ExpectError
	zvander( 'row-major', -1, 10, 10, x ); // $ExpectError
	zvander( 'row-major', -1, 10, 10, x, 1 ); // $ExpectError
	zvander( 'row-major', -1, 10, 10, x, 1, out ); // $ExpectError
	zvander( 'row-major', -1, 10, 10, x, 1, out, 10, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander.ndarray( -1, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander.ndarray( '10', 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( true, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( false, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( null, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( undefined, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( [], 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( {}, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
	zvander.ndarray( ( x: number ): number => x, 10, 10, x, 1, 0, out, 10, 1, 0 ); // $ExpectError
}

