// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );
	const out = new Complex128Array( 100 );

	zvander.ndarray(); // $ExpectError
	zvander.ndarray( -1 ); // $ExpectError
	zvander.ndarray( -1, 10 ); // $ExpectError
	zvander.ndarray( -1, 10, 10 ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1 ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1, 0 ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1, 0, out ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1, 0, out, 10 ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1, 0, out, 10, 1 ); // $ExpectError
	zvander.ndarray( -1, 10, 10, x, 1, 0, out, 10, 1, 0, 10 ); // $ExpectError
}
